// TH15 v1.00b Stage 1 wave 3.
// Source: st01.ecl.txt MainSub01:958-966 (3x GirlB01) and MainSub01b:968-982
// (9 mirrored Phantom01 pairs), started same frame by MainFront:832-833.
// Dependencies: GirlB01:252-275, GirlB01_at:277-310, Phantom01:1173-1195,
// Phantom01_at:1197-1216. Chapter entry / spawn gates / drops / ANM omitted per policy.

const TIME_LIMIT: int = 1924;   // 120 opening buffer + 1800 wave window + 4 startup slack
const OPENING_BUFFER: int = 120;

// TH15 type 8 (0x352+8*0x10) and type 5 (0x352+5*0x10), transcribe/th15/touhou-bullets.ecl.
const TH15_RICE: int = 480;
const TH15_BALL2: int = 432;

// ---------------------------------------------------------------------------
// GirlB01 (st01.ecl.txt:252-275) + GirlB01_at (277-310)
// ---------------------------------------------------------------------------
async sub girl_attack() {
    // etCountD(0,1,1,1,2, 1,1,1,1): N=1/1/1/2, M=1 all ranks.
    var ways: int = 1;
    // etSpeedD(0,1.2,1.6,2.2,4.2, 1,1,1,1) with M=1 -> first field only.
    var speed: fx = 1.2fx;
    var rounds: int = 3;      // diffI($A, 3, 8, 60, 300)
    var interval: int = 20;   // !E/!N 20; !H/!LO 10
    var r: int = global(GVAR_RANK);
    if r == RANK_NORMAL {
        rounds = 8;
        speed = 1.6fx;
    }
    if r == RANK_HARD {
        rounds = 60;
        speed = 2.2fx;
        interval = 10;
    }
    if r >= RANK_LUNATIC {
        rounds = 300;
        speed = 4.2fx;
        interval = 10;
        ways = 2;
    }

    // etAim(1) fixed-direction fan: 90 deg, or 100/80 deg at N=2.
    // etCopy(1,0) + etOffset 0=-8px / 1=+8px. Each bullet keeps the source ANIM
    // birth retreat position -= 4*velocity (policy: birth animation omitted,
    // retreat retained), so spawn 4*speed behind the gun muzzle along its angle.
    var back: fx = 4fx * speed;
    wait(60);
    for k in 0..rounds {
        for i in 0..ways {
            var a: angle = 90deg;
            if ways == 2 {
                if i == 0 { a = 100deg; } else { a = 80deg; }
            }
            var c: fx = cos(a);
            var s: fx = sin(a);
            _ = fire(TH15_RICE, 6, $self_x - 8fx - back * c, $self_y - back * s,
                     speed, a, none, none);
            _ = fire(TH15_RICE, 6, $self_x + 8fx - back * c, $self_y - back * s,
                     speed, a, none, none);
        }
        wait(interval);
    }
}

async sub girl_main() {
    set_invuln(65535);
    set_hurtbox(16fx);            // setHurtbox(32,32) circular -> r=16
    set_hitbox(12fx);             // setHitbox(24,24) circular -> r=12
    spawn girl_attack();
    move_vel(0, 90deg, 2.3fx, EASE_LINEAR);        // moveVel(pi/2, 2.3)
    move_speed(80, 0fx, EASE_QUAD_IN);             // moveVelTime(80, mode1, keep angle, 0)
    wait(180);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);   // moveVel(%ANGLE_PLAYER, 0)
    move_speed(80, 1fx, EASE_QUAD_IN);             // moveVelTime(80, mode1, keep angle, 1)
    wait(60);
    loop { wait(1); }
}

// ---------------------------------------------------------------------------
// Phantom01 (st01.ecl.txt:1173-1195) + Phantom01_at (1197-1216)
// ---------------------------------------------------------------------------
async sub phantom_attack() {
    var rounds: int = 1;   // diffI($A,1,1,1,2)
    var layers: int = 1;   // etCountD(..., 1,1,1,8)
    if global(GVAR_RANK) >= RANK_LUNATIC {
        rounds = 2;
        layers = 8;
    }

    // etAim(0,0) aimed fan, etSprite(0,5,4), etSpeedD(0,1,1,3,3,1,1,1,1):
    // H = 1 layer at speed 3; L = 8 layers 3 -> 1. Aim is resolved once per
    // volley at fire time from the owner centre. ANIM birth retreat retained.
    for k in 0..rounds {
        wait(60 + rand(90));       // wait(60 + ($RAND % 90))
        var a: angle = aim_player();
        var c: fx = cos(a);
        var s: fx = sin(a);
        for q in 0..layers {
            var sp: fx = 3fx;
            if layers > 1 { sp = 3fx + (1fx - 3fx) * q / 7; }
            var back: fx = 4fx * sp;
            _ = fire(TH15_BALL2, 4, $self_x - back * c, $self_y - back * s,
                     sp, a, none, none);
        }
    }
}

async sub phantom_main() {
    set_invuln(65535);
    set_hurtbox(14fx);             // setHurtbox(28,28) circular -> r=14
    set_hitbox(8fx);               // setHitbox(16,16) circular -> r=8
    if global(GVAR_RANK) >= RANK_HARD {
        spawn phantom_attack();    // !HL @Phantom01_at() async
    }

    // moveVel(pi/2, 1.0) + moveVelTime(120, mode3, pi/2, 1.5):
    // ABS speed 1 -> 1.5 with quartic ease-in over 120 frames.
    // moveEllipseRel(F0=0, omega=0.034906585, r=10, d=0, axis=ABS_ANGLE=pi/2, ratio=0):
    // REL offset x = 10*cos(theta), y = 0; theta advances 2 deg/frame from F0=0.
    // Mirror does not act on the ellipse setter (circular-motion rule), so both
    // members of a pair keep the same +x offset phase.
    var base_x: fx = $self_x;
    var theta: angle = 0deg;
    var t: int = 0;
    move_to(0, base_x + 10fx, $self_y, EASE_LINEAR);
    loop {
        var v: fx = 1.5fx;
        if t < 120 {
            var q: fx = (t as fx) / 120;
            var q2: fx = q * q;
            v = 1fx + 0.5fx * (q2 * q2);
        }
        var next_theta: angle = theta + 2deg;
        var dx: fx = 10fx * (cos(next_theta) - cos(theta));
        move_vel_xy(0, dx, v, EASE_LINEAR);
        theta = next_theta;
        t = t + 1;
        wait(1);
    }
}

// ---------------------------------------------------------------------------
// Wave schedule: MainSub01 and MainSub01b start on the same frame.
// Girls at source t=0/60/120; phantom pairs at t=0/30/.../240 (A=16..144).
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(128fx, -24fx, 600, 0, 1000, 0, girl_main);
    _ = spawn_enemy(16fx, -24fx, 90, 0, 1000, 0, phantom_main);
    _ = spawn_enemy(-16fx, -24fx, 90, 0, 1000, 0, phantom_main);
    wait(30);
    _ = spawn_enemy(32fx, -24fx, 90, 0, 1000, 0, phantom_main);
    _ = spawn_enemy(-32fx, -24fx, 90, 0, 1000, 0, phantom_main);
    wait(30);
    _ = spawn_enemy(-128fx, -24fx, 600, 0, 1000, 0, girl_main);
    _ = spawn_enemy(48fx, -24fx, 90, 0, 1000, 0, phantom_main);
    _ = spawn_enemy(-48fx, -24fx, 90, 0, 1000, 0, phantom_main);
    wait(30);
    _ = spawn_enemy(64fx, -24fx, 90, 0, 1000, 0, phantom_main);
    _ = spawn_enemy(-64fx, -24fx, 90, 0, 1000, 0, phantom_main);
    wait(30);
    _ = spawn_enemy(0fx, -24fx, 600, 0, 1000, 0, girl_main);
    _ = spawn_enemy(80fx, -24fx, 90, 0, 1000, 0, phantom_main);
    _ = spawn_enemy(-80fx, -24fx, 90, 0, 1000, 0, phantom_main);
    wait(30);
    _ = spawn_enemy(96fx, -24fx, 90, 0, 1000, 0, phantom_main);
    _ = spawn_enemy(-96fx, -24fx, 90, 0, 1000, 0, phantom_main);
    wait(30);
    _ = spawn_enemy(112fx, -24fx, 90, 0, 1000, 0, phantom_main);
    _ = spawn_enemy(-112fx, -24fx, 90, 0, 1000, 0, phantom_main);
    wait(30);
    _ = spawn_enemy(128fx, -24fx, 90, 0, 1000, 0, phantom_main);
    _ = spawn_enemy(-128fx, -24fx, 90, 0, 1000, 0, phantom_main);
    wait(30);
    _ = spawn_enemy(144fx, -24fx, 90, 0, 1000, 0, phantom_main);
    _ = spawn_enemy(-144fx, -24fx, 90, 0, 1000, 0, phantom_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
